 static long Count(string sql)=>Convert.ToInt64(Sql(sql));
 static decimal Value(string sql)=>Convert.ToDecimal(Sql(sql));
 static void Pump(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(25);do{Application.DoEvents();Thread.Sleep(20);}while(!done()&&DateTime.UtcNow<end);if(!done())throw new Exception("Timed out waiting for UI");}
 static IEnumerable<Control> All(Control c)=>new[]{c}.Concat(c.Controls.Cast<Control>().SelectMany(All));
 static void Reject(Action a,string text){bool refused=false;try{a();}catch(InvalidDataException){refused=true;}catch(InvalidOperationException){refused=true;}Check(refused,text);}
 static void Capture(Form f,string n){using var image=new Bitmap(f.Width,f.Height);f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save("corrections-evidence/"+n+".png");}
 [STAThread]static int Main(){
 if(!OperatingSystem.IsWindows()||Environment.GetEnvironmentVariable("GITHUB_ACTIONS")!="true")throw new Exception("Isolated Windows only");
 Directory.CreateDirectory("corrections-evidence");using var watchdog=new System.Threading.Timer(_=>Environment.Exit(90),null,130000,Timeout.Infinite);
 try{
