 Check(batch.Length==2&&batch.Single(d=>d.TableOnly).Items.Length==1&&batch.Single(d=>!d.TableOnly).Items.Length==2,"mixed ticket splits only selected direct and preparation items");
 Check(batch.SelectMany(d=>d.Items).Sum(i=>i.Quantity*i.UnitPrice)==66&&batch.All(d=>d.Reference=="Mesa 02"&&d.Notes=="mesa mista"),"grouping preserves quantities unit prices observations and table reference");
 Reject(()=>KitchenDraftDestinations.Create("","","QA",new[]{new KitchenDraftDestination(Juice(1),true)}),"direct portion requires a table");
 Reject(()=>queue.QueueBatch(id,new[]{batch[0],batch[1] with{Items=new[]{Juice(0)}}}),"invalid second group is rejected before any queue write");Check(queue.Pending().Count==0,"rejected mixed ticket leaves no partial durable queue");
 queue.QueueBatch(id,batch);Check(Directory.GetFiles(folder,"*.batch").Length==1&&queue.Pending().Count==2,"all mixed destinations are protected in one atomic durable file");queue.QueueBatch(id,batch);Check(queue.Pending().Count==2,"retrying identical queued batch does not duplicate groups");
 store.Submit(id,batch[0]);var restarted=new KitchenOutbox(folder);Check(restarted.Pending().Count==2,"restart after first group committed retains complete pending batch");restarted.Flush(store);Check(restarted.Pending().Count==0&&store.ListActive().Count(o=>o.Reference=="Mesa 02")==2,"recovery reuses stable identities and creates missing group exactly once");
 var direct=store.Get(batch.Single(d=>d.TableOnly).Id);var prep=store.Get(batch.Single(d=>!d.TableOnly).Id);
 Check(direct.Status=="ENTREGUE"&&direct.TableOnly&&prep.Status=="AGUARDANDO"&&!prep.TableOnly,"direct group has no preparation while kitchen group starts waiting");using(var panel=new KitchenOrderPanel()){panel.Display("Mesa 02",direct.Items,true,direct.ReceivedUtc,true,"ENTREGUE",direct.Items.Select(i=>new KitchenTableLine(direct.Id,i.Position??0,direct.Status,true,i)).ToArray());Check(Field<DateTimeOffset?>(panel,"started")==null,"direct items never start a preparation timer");panel.Display("Mesa 02",prep.Items,true,prep.ReceivedUtc,true,"AGUARDANDO",prep.Items.Select(i=>new KitchenTableLine(prep.Id,i.Position??0,prep.Status,false,i)).ToArray());Check(Field<DateTimeOffset?>(panel,"started").HasValue,"only preparation items start the kitchen timer");}
 Check(direct.Items.Single().Quantity==3&&prep.Items.Sum(i=>i.Quantity)==3.5m,"recovery preserves all original quantities");
