 var legacy=new KitchenOutbox(Path.Combine(Database.AppFolder,"QA-LEGACY"));var old=new KitchenDraft(Guid.NewGuid(),"Mesa 04","","QA",DateTimeOffset.UtcNow,new[]{Juice(1)},true);legacy.Queue(id,old);legacy.Flush(store);Check(store.Get(old.Id).TableOnly&&legacy.Pending().Count==0,"existing single-order pending files remain fully compatible");
 var quote=store.Quote(direct.Id);Reject(()=>KitchenStore.SelectItems(quote,quote.Items.Select(i=>new KitchenPayQuantity(i.OrderId,i.Position,i.Quantity)).ToArray(),true),"total payment remains blocked by mixed preparation group");var selected=KitchenStore.SelectItems(quote,new[]{new KitchenPayQuantity(direct.Id,0,1)});var sale=store.Receive(selected,new[]{new KitchenPayment("PIX",5)},"QA");Check(Value("SELECT stock FROM products WHERE id=1")==99&&Value("SELECT stock FROM products WHERE id=2")==100&&store.Get(direct.Id).Items.Single().Quantity==2,"partial payment deducts only delivered quantity and retains remaining direct items");Check(store.Receive(selected,new[]{new KitchenPayment("PIX",5)},"QA")==sale&&Value("SELECT stock FROM products WHERE id=1")==99,"mixed partial-payment retry cannot duplicate money or stock");
 InternalWorkspace.Install();PremiumGlobalTheme.Install();using var form=new KitchenForm();form.Show();var menu=Field<KitchenCatalogView>(form,"mainCatalog");var fresh=Field<Button>(form,"fresh");Pump(()=>fresh.Enabled&&menu.Controls.Find("CatalogProduct_1",true).Length==1&&menu.Controls.Find("CatalogReload",true).OfType<Button>().Single().Enabled);Field<System.Windows.Forms.Timer>(form,"retry").Stop();Call(form,"OpenEntryForTable",1);var grid=Field<DataGridView>(form,"items");
 foreach(var p in KitchenCatalogView.ReadProducts())Call(form,"ChooseProduct",p);
 Check(grid.Rows.Count==3&&grid.Columns["Destination"] is DataGridViewButtonColumn&&grid.Rows.Cast<DataGridViewRow>().All(r=>Convert.ToString(r.Cells["Destination"].Value)!.EndsWith("▼")),"real NEW ORDER shows a left-click destination arrow beside every selected product");
 Check(grid.Rows.Cast<DataGridViewRow>().All(r=>r.Cells["Destination"].Tag is KitchenRowDestination{TableOnly:false,Chosen:false}),"classification supplies initial per-item preparation suggestions");
 int juiceIndex=grid.Rows.Cast<DataGridViewRow>().Single(r=>Convert.ToInt64(r.Tag)==1).Index;
 typeof(DataGridView).GetMethod("OnCellContentClick",P)!.Invoke(grid,new object[]{new DataGridViewCellEventArgs(grid.Columns["Destination"].Index,juiceIndex)});Application.DoEvents();var destinations=Field<ContextMenuStrip>(form,"destinationMenu");Check(destinations.Visible&&destinations.Items.Count==2&&destinations.Items[0].Text=="ADICIONAR À MESA"&&destinations.Items[1].Text=="ENVIAR PARA PREPARO","left-click arrow opens exactly the two requested destination options");((ToolStripMenuItem)destinations.Items[0]).PerformClick();if(!destinations.IsDisposed)destinations.Close();
 Check(grid.Rows[juiceIndex].Cells["Destination"].Tag is KitchenRowDestination{TableOnly:true,Chosen:true},"manual juice destination overrides this order only");
 grid.CurrentCell=grid.Rows[juiceIndex].Cells[0];Call(form,"EditDashboardItem",juiceIndex);Field<NumericUpDown>(form,"itemQuantity").Value=3;Call(form,"AddDraftItem");Check(grid.Rows[juiceIndex].Cells["Destination"].Tag is KitchenRowDestination{TableOnly:true,Chosen:true},"editing quantity preserves explicit route on the same product");
 foreach(DataGridViewRow row in grid.Rows)if(Convert.ToInt64(row.Tag)!=1){int index=row.Index;Call(form,"OpenDestinationMenu",index);var choices=Field<ContextMenuStrip>(form,"destinationMenu");((ToolStripMenuItem)choices.Items[1]).PerformClick();if(!choices.IsDisposed)choices.Close();}
 var entry=Field<Form>(form,"entryWindow");Check(KitchenPremiumStyle.Owns(entry)&&entry.BackColor==KitchenPremiumStyle.Background,"mixed destination editor retains premium black and gold visual");Capture(entry,"novo-pedido-destinos");
 long priorOrders=Count("SELECT COUNT(*) FROM kitchen_orders_v1");int alerts=0;using var alertWatch=new System.Windows.Forms.Timer{Interval=50};alertWatch.Tick+=(_,_)=>{if(FindWindow(null,"Conferir destino dos produtos")!=IntPtr.Zero){alerts++;throw new Exception("Unnecessary classification alert after explicit choices");}};alertWatch.Start();Field<Button>(form,"send").PerformClick();Pump(()=>fresh.Enabled&&Count("SELECT COUNT(*) FROM kitchen_orders_v1")==priorOrders+2);alertWatch.Stop();Check(alerts==0,"confirming explicit destinations sends mixed ticket without redundant alerts");
 var saved=store.ListActive().Where(o=>o.Reference=="Mesa 01"&&o.Id!=initial.Id).ToArray();Check(saved.Length==2&&saved.Single(o=>o.TableOnly).Items.Single().ProductId==1&&saved.Single(o=>!o.TableOnly).Items.Length==2,"existing confirm button routes juice to table and beans and soup to kitchen");Check(store.Get(initial.Id).Items.Single().Quantity==1,"existing table consumption remains unchanged by a new mixed order");Check(Convert.ToInt32(Sql("SELECT kitchen_route FROM products WHERE id=1"))==1,"per-order manual destination never rewrites product classification");
 Check(Count("SELECT COUNT(*) FROM sales")==1&&Value("SELECT stock FROM products WHERE id=1")==99,"real UI mixed send preserves payments and stock");Check(KitchenTablesView.State(store.ListActive(),1)!="LIVRE"&&KitchenTablesView.State(store.ListActive(),2)!="LIVRE","tables stay occupied with active consumption or preparation");
 form.Close();Check(Convert.ToString(Sql("PRAGMA quick_check"))=="ok","database integrity remains valid after mixed submission recovery and payment");
 File.WriteAllText("corrections-evidence/results.json",JsonSerializer.Serialize(new{success=true,channel="003",source=Environment.GetEnvironmentVariable("APPROVED_SOURCE"),checks,nativeWindows=true,published=false}));Console.WriteLine("PASS MIXED DESTINATIONS 003 ONLY");Environment.Exit(0);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);File.WriteAllText("corrections-evidence/failure.txt",e.ToString());return 1;}
